// Auto-integrate all entries from NAMES_DICTIONARY_ENTRIES into NAMES_DICT and NAMES_URDU_TO_ENG
// Pass 1: Primary names have strict priority over legacy entries and aliases
for (const entry of NAMES_DICTIONARY_ENTRIES) {
  const cleanEn = entry.en.toLowerCase().replace(/[^a-z]/g, '');
  if (cleanEn) {
    NAMES_DICT[cleanEn] = entry.ur;
  }
  if (entry.ur && !NAMES_URDU_TO_ENG[entry.ur]) {
    NAMES_URDU_TO_ENG[entry.ur] = entry.en;
  }
}

// Pass 2: Aliases and spelling variations populate remaining slots
for (const entry of NAMES_DICTIONARY_ENTRIES) {
  if (entry.aliasesEn) {
    for (const alias of entry.aliasesEn) {
      const cleanAlias = alias.toLowerCase().replace(/[^a-z]/g, '');
      if (cleanAlias && !NAMES_DICT[cleanAlias]) {
        NAMES_DICT[cleanAlias] = entry.ur;
      }
    }
  }
  if (entry.aliasesUr) {
    for (const aliasUr of entry.aliasesUr) {
      if (!NAMES_URDU_TO_ENG[aliasUr]) {
        NAMES_URDU_TO_ENG[aliasUr] = entry.en;
      }
    }
  }
}

